from pathlib import Path
import json
R=Path('06_resultados'); rows=json.loads((R/'soporte/fragmentos.json').read_text(encoding='utf-8')); by={r['ref']:r for r in rows}
clusters=[
('C1','Registrar sin frenar la atención','A2','E01-F03 E03-F03 E03-F07 E10-F02 E10-F07 E10-F10 E13-F05',[2,2,3,3],'E10 omite ventas con afluencia y deja la app por atención y enfoque; E03/E13 anticipan carga; E01 estima 30–45 minutos al cierre.','El costo de capturar puede anular el valor de tener datos. El mecanismo de abandono solo está documentado en E10.','Captura lenta y percepción de demora del cliente; el escáner de PC es una preferencia futura, no superioridad medida.','Moderada: conducta pasada concreta en E10, percepciones en los otros casos; sin cronometraje.','Comparar registro móvil y flujo actual en hora de afluencia, con precisión y espera del cliente como medidas.'),
('C2','Actuar sobre rotación y fechas','A5','E04-F07 E07-F08 E09-F04 E09-F05 E10-F11 E10-F12 E11-F02 E11-F03 E11-F07 E11-F09 E14-F05 E16-F03 E16-F04',[2,2,3,3],'E10/E16 relatan dificultades con fechas; E14 busca control de perecederos; E09 tuvo stock estacional inmovilizado; E11 repone a ojo y quiere mejorar surtido. E04 aporta organización documental y E07 faltantes poco explorados.','El valor puede estar en decisiones puntuales de compra y rotación, no en registrar por registrar. Son subproblemas que requieren pruebas separadas.','Visibilidad limitada, demanda variable y revisión de fechas insuficiente; no hay causa única ni pérdida monetaria demostrada por vencimiento.','Moderada: varios relatos, pero distintos negocios y pocos episodios medidos. E14 es florería; excluirla reduce el conteo en uno sin cambiar la banda.','Priorizar un grupo de perecederos en abarrotes; medir unidades, devolución/descarte y decisiones. Explorar documentos y precios como tareas distintas.'),
('C3','Ajustar la herramienta al negocio','A4','E01-F06 E02-F05 E02-F06 E02-F07 E05-F05 E06-F07 E07-F05 E07-F06 E10-F09 E14-F02 E14-F03 E14-F04 E15-F04 E15-F05',[2,2,3,3],'Hay discontinuidad declarada en E01, contratación a medida en E02, límite de carga en E06 y búsqueda de especialización en E14. E05 percibe software grande; E15 está satisfecho y E10 reconoce funciones útiles.','Ya existen alternativas; oportunidad y exigencias cambian por operación. No asumir que precio bajo o móvil bastan para competir.','Desajuste de procesos, mantenimiento y capacidad; verificar cada fallo antes de atribuirlo a todo software.','Moderada: acciones previas fuertes en E02/E14, pero requerimientos de E02 incompletos. Incluye contraejemplos, no nueve casos insatisfechos.','Reconstruir tareas y alternativas usadas; validar continuidad, soporte y carga antes de ampliar funciones.'),
('C4','Habilitar a todos los operadores','A3','E01-F07 E02-F01 E06-F05 E06-F06 E08-F06 E08-F07 E13-F06 E16-F09',[2,2,3,3],'E01 frena adopción por una persona que no usa celular, E08 encuentra dificultad y E16 delega QR al hijo. E02/E06 controlan por operador; E13 condiciona interés a contratar.','La unidad de adopción puede ser el equipo de atención, no solo el dueño entrevistado. Solo tres casos describen barrera de habilidad.','Habilidades desiguales y flujo compartido; edad no basta para explicar la dificultad.','Moderada: freno explícito y dependencia declarada, sin prueba con cada operador.','Probar tareas con dueño, familiar y reemplazo; medir autonomía y registro completo por turno.'),
('C5','Demostrar mejora frente a hábitos suficientes','A1','E03-F02 E04-F03 E05-F02 E05-F04 E08-F01 E09-F01 E12-F04 E13-F01 E13-F08 E15-F05 E16-F06',[3,1,2,3],'Nueve casos justifican o aceptan el método actual, desde cuaderno a software. E12 relaciona ausencia de registro con volumen mínimo.','No hay urgencia uniforme de digitalización. Suficiencia percibida no acredita exactitud ni ausencia de dolores específicos.','Escala, hábito, control individual o alternativa instalada reducen beneficio percibido de cambiar.','Moderada para percepción declarada recurrente; débil para rendimiento real. Perfiles heterogéneos, no una prevalencia de todas las tiendas.','Exigir beneficio demostrado en una tarea y comprador identificado antes de vender sustitución integral.'),
('C6','Verificar cobros QR sin detener la venta','A7','E08-F08 E08-F09 E15-F07 E15-F08 E16-F09',[2,2,2,2],'E08 desconfía de comprobantes, E15 espera confirmación y E16 depende del hijo.','Verificar recepción y poder operar QR son tareas distintas. No confundir ambas con registro de inventario.','Demora de confirmación, sospecha de comprobantes y habilidad familiar según relatos.','Moderada para fricciones, débil para fraude consumado y magnitud.','Observar confirmación y entrega, separando demora de aprendizaje; validar viabilidad antes de prometer integración bancaria.'),
('C7','Delimitar el fiado antes de digitalizarlo','A6','E01-F04 E01-F05 E02-F04 E03-F04 E03-F05 E04-F05 E05-F03 E06-F04 E08-F03 E08-F04 E10-F03 E10-F04 E11-F11 E11-F12 E15-F06 E16-F08',[3,2,2,3],'Crédito empresarial en E01, rechazo y garantías en varios casos, excepciones de confianza en E08/E10/E11/E16. Hay impago histórico en E01/E03/E11.','El problema incluye voluntad de pago y política comercial. Un registro no garantiza cobrar; no hay pérdida mensual cuantificada.','Experiencia de impago o cautela; en E10 además se olvida capturar consumos.','Moderada para políticas y episodios pasados; débil para S2 mensual. Los 11 casos representan prácticas de crédito, no 11 casos de pérdida.','Entrevistar por separado a fiadores actuales, crédito empresarial y quienes dejaron de fiar; reconstruir último saldo y motivo de impago.'),
('C8','Reconocer restricciones económicas externas','A8','E04-F02 E07-F02 E09-F08 E11-F04 E11-F13 E12-F01 E12-F05 E14-F08 E14-F09',[2,3,3,1],'Bajas ventas, electricidad, amenazas y abastecimiento interrumpido dominan parte de los relatos.','Un problema intenso puede estar fuera del alcance del registro digital. La tienda también puede cumplir función de actividad cotidiana.','Factores económicos y de continuidad según los participantes; no son hechos externos verificados.','Moderada para experiencia y preocupación, débil para atribución causal y prevalencia.','Seleccionar participantes con tarea abordable por Qhatu y registrar causas externas al evaluar un piloto.')]
summary=[]; out=['''# Affinity map de Qhatu con 16 entrevistas

## 1. Resumen ejecutivo

La muestra incorpora aceptación de registros manuales, limitaciones de software y necesidades operativas distintas.
E10 aporta el contraejemplo más directo al supuesto móvil: abandonó una app útil porque afectaba la atención.
Fechas y rotación reaparecen en E10/E16; E14 aporta una necesidad similar en florería, un perfil adyacente.
E01/E08/E16 muestran que las habilidades familiares condicionan la adopción.
Los impagos previos en E01/E03/E11 amplían la evidencia de fiado, sin validar pérdidas mensuales ni causas de registro.
Pago por alternativas y búsqueda de desarrollo propio no prueban disposición a pagar por Qhatu.
La siguiente decisión debe basarse en pruebas de tareas con los operadores reales, no en construir todo el alcance propuesto.

### Criterios y denominadores

Frecuencia: 1 para 1–2 entrevistas, 2 para 3–8 y 3 para 9–16 (mayoría estricta). El tramo intermedio operacionaliza la escala del proyecto. Se cuenta cada entrevista una vez por cluster; los clusters se superponen. Los 16 incluyen florería, micromarket y baja actividad; se muestra sensibilidad sin florería y no se afirma representatividad.

Intensidad: 1 neutra, 2 molestia/valoración explícita, 3 preocupación fuerte. Impacto: 3 si el relato afecta continuidad, dinero, captura o adopción; 2 dificultad localizada sin magnitud acreditada. Relevancia: 3 central a registro/inventario/fiado, 2 cobro relacionado, 1 restricción externa. Los puntajes son juicio analítico; alta 10–12, media 7–9, baja 4–6. Una prioridad alta puede exigir refutar una hipótesis, no construir una función.

## 2. Clusters identificados
''']
for c in sorted(clusters,key=lambda c:-sum(c[4])):
 id,name,ax,rr,score,pattern,interp,cause,strength,opp=c; rr=rr.split(); es=sorted({by[r]['entrevista'] for r in rr}); freq=1 if len(es)<=2 else 2 if len(es)<=8 else 3
 assert freq==score[0],(id,es,score)
 total=sum(score); level='Alta' if total>=10 else 'Media' if total>=7 else 'Baja'
 out.append(f'### {id} {name}\n\n**Descripción del patrón:** {pattern}\n\n**Insights agrupados:** categoría {ax}.\n\n'+'\n'.join(f'- {by[r]["codigo"]}: “{by[r]["cita"]}” ({r}).' for r in rr)+f'\n\n**Interpretación profunda:** {interp}\n\n**Posible causa raíz:** {cause}\n\n**Nivel de relevancia:** {level}.\n\n| Frecuencia | Intensidad | Impacto | Relevancia | Total |\n|---|---|---|---|---|\n| '+ ' | '.join(map(str,score+[total]))+' |\n\n**Base del puntaje:** '+f'{len(es)}/16 casos: '+', '.join(es)+f'. Intensidad e impacto se apoyan en los relatos anteriores; no son promedios ni montos de pérdida. '+('En C7, impacto 2 conserva incertidumbre por falta de fecha/monto, aunque existen deudas relatadas.' if id=='C7' else '')+f'\n\n**Solidez de la evidencia:** {strength}\n\n**Oportunidad potencial:** {opp}\n')
 summary.append(f'| {id} {name} | {level} | {total}/12 | {len(es)}/16 | {opp} |')
 out.append('**Sensibilidad sin E14:** '+f'{len([e for e in es if e!="E14"])}/15 entrevistas; '+('la banda de frecuencia cambia de 2 a 3 porque 8/15 es mayoría; el puntaje aumentaría en uno.' if len(es)==8 and 'E14' not in es else 'la banda de frecuencia no cambia.')+'\n')
(R/'03_affinity_map.md').write_text('\n'.join(out)+'\n## 3. Tabla resumen de clusters\n\n| Cluster | Relevancia | Puntaje | Nº de entrevistas | Oportunidad principal |\n|---|---|---|---|---|\n'+'\n'.join(summary)+'\n',encoding='utf-8')
(R/'soporte/clusters.json').write_text(json.dumps([dict(id=c[0],nombre=c[1],refs=c[3].split(),puntajes=c[4]) for c in clusters],ensure_ascii=False,indent=2),encoding='utf-8')
print('Clusters verificados')
